<?php
declare(strict_types=1);
namespace DoomPhonics\Tools;

/**
 * Supply the demos' original tileable water flat without borrowing IWAD artwork.
 *
 * Integer waves in Doom's blue palette ramp keep the generated bytes portable
 * and deterministic. The same texture works with the shareware IWAD.
 */
final class WaterFlat
{
	/** Encode one 64-by-64 indexed flat. */
	public static function bytes(): string
	{
		$water = '';
		$wave = static function(int $phase): int {
			$phase &= 31;
			return $phase < 16 ? $phase : 31 - $phase;
		};
		for($y=0;$y<64;$y++)
		for($x=0;$x<64;$x++)
		{
			$ripple = $wave($x + intdiv($wave($y*2),2)) + $wave($y + intdiv($wave($x*2),2));
			$water .= chr(198 + intdiv($ripple,4));
		}
		return $water;
	}
}
